import React, { useState } from 'react';
import api from '../../config/axiosConfig';
import { toast } from 'react-toastify';

interface PurchaseRequestFormProps {
    onSuccess?: () => void;
}

const PurchaseRequestForm: React.FC<PurchaseRequestFormProps> = ({ onSuccess }) => {
    const [loading, setLoading] = useState(false);
    const [formData, setFormData] = useState({
        productOrService: '',
        description: '',
        quantity: 1,
        referenceLink: '',
        deliveryDeadline: '',
        image: null as File | null
    });

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        const { name, value, type } = e.target;
        const val = type === 'number' ? parseInt(value, 10) || 1 : value;
        setFormData(prev => ({ ...prev, [name]: val }));
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        setFormData(prev => ({ ...prev, image: file || null }));
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!formData.productOrService.trim() || !formData.description.trim()) {
            toast.error('Producto/servicio y descripción son obligatorios.');
            return;
        }

        setLoading(true);
        try {
            const payload = {
                productOrService: formData.productOrService.trim(),
                description: formData.description.trim(),
                quantity: formData.quantity,
                referenceLink: formData.referenceLink.trim() || undefined,
                deliveryDeadline: formData.deliveryDeadline || undefined
            };
            // La imagen se manejará en Fase 2 (Firebase Storage)
            await api.post('/api/purchases', payload);

            toast.success('Solicitud de compra creada correctamente.');
            setFormData({
                productOrService: '',
                description: '',
                quantity: 1,
                referenceLink: '',
                deliveryDeadline: '',
                image: null
            });
            onSuccess?.();
        } catch (error: unknown) {
            const err = error as { response?: { data?: { message?: string } } };
            toast.error(err.response?.data?.message || 'Error al crear la solicitud.');
        } finally {
            setLoading(false);
        }
    };

    return (
        <form onSubmit={handleSubmit} className="bg-white rounded-lg shadow p-6 space-y-4">
            <h2 className="text-xl font-bold text-gray-800 mb-4">Nueva solicitud de compra</h2>

            <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Producto o servicio *</label>
                <input
                    type="text"
                    name="productOrService"
                    value={formData.productOrService}
                    onChange={handleChange}
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-red-500 focus:border-red-500"
                    placeholder="Ej: Monitor Dell 24 pulgadas"
                    required
                />
            </div>

            <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Descripción de la necesidad *</label>
                <textarea
                    name="description"
                    value={formData.description}
                    onChange={handleChange}
                    rows={4}
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-red-500 focus:border-red-500"
                    placeholder="Describa por qué necesita este producto/servicio..."
                    required
                />
            </div>

            <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Cantidad *</label>
                <input
                    type="number"
                    name="quantity"
                    value={formData.quantity}
                    onChange={handleChange}
                    min={1}
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-red-500 focus:border-red-500"
                />
            </div>

            <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Link de referencia</label>
                <input
                    type="url"
                    name="referenceLink"
                    value={formData.referenceLink}
                    onChange={handleChange}
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-red-500 focus:border-red-500"
                    placeholder="https://..."
                />
            </div>

            <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Fecha tope de entrega</label>
                <input
                    type="date"
                    name="deliveryDeadline"
                    value={formData.deliveryDeadline}
                    onChange={handleChange}
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-red-500 focus:border-red-500"
                />
            </div>

            <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Imagen (opcional)</label>
                <input
                    type="file"
                    accept="image/*"
                    onChange={handleFileChange}
                    className="w-full px-3 py-2 border border-gray-300 rounded-md text-sm"
                />
                <p className="text-xs text-gray-500 mt-1">La subida a Storage se habilitará en la siguiente fase.</p>
            </div>

            <button
                type="submit"
                disabled={loading}
                className="w-full bg-red-600 hover:bg-red-700 text-white font-semibold py-2 px-4 rounded-md disabled:opacity-50"
            >
                {loading ? 'Enviando...' : 'Enviar solicitud'}
            </button>
        </form>
    );
};

export default PurchaseRequestForm;
