import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../../config/axiosConfig';
import { toast } from 'react-toastify';
import InviteSupplierModal from './InviteSupplierModal';
import HelpBox from '../Common/HelpBox';

interface AreaSummary {
    departmentId: number;
    departmentName: string;
    total: number;
    newCount: number;
    purchases: { id: string; productOrService: string; status: string; createdAt?: string }[];
}

interface Purchase {
    id: string;
    productOrService: string;
    description: string;
    quantity: number;
    referenceLink?: string;
    deliveryDeadline?: string;
    requesterUsername: string;
    status: string;
    departmentId?: number;
    createdAt: string;
}

const PURCHASING_STATUSES = [
    'Aprobado por Jefe',
    'Recibido',
    'Esperando presupuesto',
    'Compra Aprobada',
    'Esperando entrega',
    'Entregado',
    'Conforme / Cerrado'
];

const PurchasingAgentDashboard: React.FC = () => {
    const navigate = useNavigate();
    const [view, setView] = useState<'areas' | 'list'>('areas');
    const [selectedArea, setSelectedArea] = useState<AreaSummary | null>(null);
    const [areas, setAreas] = useState<AreaSummary[]>([]);
    const [purchases, setPurchases] = useState<Purchase[]>([]);
    const [loading, setLoading] = useState(true);
    const [statusLoading, setStatusLoading] = useState<string | null>(null);
    const [inviteModalOpen, setInviteModalOpen] = useState(false);

    const fetchDashboard = async () => {
        setLoading(true);
        try {
            const { data } = await api.get('/api/purchases/dashboard');
            if (data.success && data.data?.areas) {
                setAreas(data.data.areas);
            } else {
                toast.error(data.message || 'Error al cargar dashboard.');
            }
        } catch (error: unknown) {
            const err = error as { response?: { data?: { message?: string }; status?: number } };
            if (err.response?.status === 503) {
                toast.error('El módulo de compras no está disponible.');
            } else {
                toast.error(err.response?.data?.message || 'Error al cargar.');
            }
        } finally {
            setLoading(false);
        }
    };

    const fetchPurchasesByArea = async (departmentId: number) => {
        setLoading(true);
        try {
            const { data } = await api.get(`/api/purchases/all?departmentId=${departmentId}`);
            if (data.success && data.data) {
                setPurchases(data.data);
            }
        } catch {
            toast.error('Error al cargar solicitudes.');
        } finally {
            setLoading(false);
        }
    };

    const handleAreaClick = (area: AreaSummary) => {
        setSelectedArea(area);
        setView('list');
        fetchPurchasesByArea(area.departmentId);
    };

    const handleBackToAreas = () => {
        setView('areas');
        setSelectedArea(null);
        setPurchases([]);
    };

    const handleStatusChange = async (id: string, newStatus: string) => {
        setStatusLoading(id);
        try {
            const { data } = await api.put(`/api/purchases/${id}/status`, { status: newStatus });
            if (data.success) {
                toast.success('Estado actualizado.');
                setPurchases(prev =>
                    prev.map(p => (p.id === id ? { ...p, status: newStatus } : p))
                );
            } else {
                toast.error(data.message || 'Error al actualizar.');
            }
        } catch (error: unknown) {
            const err = error as { response?: { data?: { message?: string } } };
            toast.error(err.response?.data?.message || 'Error al actualizar.');
        } finally {
            setStatusLoading(null);
        }
    };

    const formatDate = (dateStr?: string) => {
        if (!dateStr) return '-';
        return new Date(dateStr).toLocaleDateString('es-AR', {
            day: '2-digit',
            month: '2-digit',
            year: 'numeric',
            hour: '2-digit',
            minute: '2-digit'
        });
    };

    const getStatusColor = (status: string) => {
        if (status === 'Entregado' || status === 'Conforme / Cerrado') return 'bg-green-100 text-green-800';
        if (status === 'Rechazado') return 'bg-red-100 text-red-800';
        if (status.includes('Esperando')) return 'bg-amber-100 text-amber-800';
        if (status.includes('Aprobad')) return 'bg-blue-100 text-blue-800';
        return 'bg-gray-100 text-gray-800';
    };

    useEffect(() => {
        if (view === 'areas') fetchDashboard();
    }, [view]);

    if (view === 'areas') {
        return (
            <div className="space-y-6">
                <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                    <div>
                        <h1 className="text-2xl font-bold text-gray-800">Gestión de compras por área</h1>
                        <p className="text-gray-600">Seleccione un área para ver sus solicitudes de compra.</p>
                    </div>
                    <button
                        onClick={() => setInviteModalOpen(true)}
                        className="px-4 py-2 bg-red-600 hover:bg-red-700 text-white font-medium rounded-md"
                    >
                        Invitar Proveedor
                    </button>
                </div>
                <HelpBox title="¿Cómo funciona la gestión de compras?" defaultExpanded={true}>
                    <p><strong>1.</strong> Seleccione un área (departamento) para ver las solicitudes de compra que requieren su gestión.</p>
                    <p><strong>2.</strong> Cada solicitud pasa por estados: Aprobado por Jefe → Recibido → Esperando presupuesto → Compra aprobada → Esperando entrega → Entregado → Conforme/Cerrado.</p>
                    <p><strong>3.</strong> Al hacer clic en una solicitud puede solicitar presupuestos a los proveedores registrados e indicar sus preferencias de pago.</p>
                    <p><strong>4.</strong> Una vez recibidas las cotizaciones, seleccione el ganador. El proveedor recibirá notificaciones (email, push, WhatsApp) y podrá subir la factura.</p>
                    <p><strong>5.</strong> Use "Invitar Proveedor" para agregar o reenviar el link de activación a proveedores registrados.</p>
                </HelpBox>
                <InviteSupplierModal
                    isOpen={inviteModalOpen}
                    onClose={() => setInviteModalOpen(false)}
                    onSuccess={() => {}}
                />

                {loading ? (
                    <div className="bg-white rounded-lg shadow p-8 text-center text-gray-500">
                        Cargando...
                    </div>
                ) : areas.length === 0 ? (
                    <div className="bg-white rounded-lg shadow p-8 text-center text-gray-500">
                        No hay compras aprobadas para gestionar.
                    </div>
                ) : (
                    <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
                        {areas.map((area) => (
                            <button
                                key={area.departmentId}
                                onClick={() => handleAreaClick(area)}
                                className="bg-white rounded-lg shadow p-5 border border-gray-200 hover:shadow-md hover:border-red-200 transition-all text-left"
                            >
                                <h3 className="font-bold text-gray-800 text-lg mb-2">{area.departmentName}</h3>
                                <div className="flex flex-wrap gap-2 text-sm">
                                    <span className="px-2 py-1 bg-gray-100 rounded">
                                        Total: <strong>{area.total}</strong>
                                    </span>
                                    {area.newCount > 0 && (
                                        <span className="px-2 py-1 bg-amber-100 text-amber-800 rounded">
                                            Nuevas: <strong>{area.newCount}</strong>
                                        </span>
                                    )}
                                </div>
                            </button>
                        ))}
                    </div>
                )}
            </div>
        );
    }

    return (
        <div className="space-y-6">
                <div className="flex flex-col sm:flex-row justify-between items-start gap-4">
                <div className="flex items-center gap-4">
                    <button
                        onClick={handleBackToAreas}
                        className="text-gray-600 hover:text-gray-800 font-medium"
                    >
                        ← Volver a áreas
                    </button>
                    <h1 className="text-2xl font-bold text-gray-800">
                        Solicitudes de {selectedArea?.departmentName || ''}
                    </h1>
                </div>
                <button
                    onClick={() => setInviteModalOpen(true)}
                    className="px-4 py-2 bg-red-600 hover:bg-red-700 text-white font-medium rounded-md self-start"
                >
                    Invitar Proveedor
                </button>
            </div>
                <InviteSupplierModal
                    isOpen={inviteModalOpen}
                    onClose={() => setInviteModalOpen(false)}
                    onSuccess={() => {}}
                />

            {loading ? (
                <div className="bg-white rounded-lg shadow p-8 text-center text-gray-500">
                    Cargando...
                </div>
            ) : purchases.length === 0 ? (
                <div className="bg-white rounded-lg shadow p-8 text-center text-gray-500">
                    No hay solicitudes en esta área.
                </div>
            ) : (
                <div className="grid gap-4 sm:grid-cols-1 lg:grid-cols-2">
                    {purchases.map((p) => (
                        <div
                            key={p.id}
                            className="bg-white rounded-lg shadow p-5 border border-gray-200 hover:shadow-md transition-shadow"
                        >
                            <div className="flex justify-between items-start mb-3">
                                <button
                                    onClick={() => navigate(`/purchases/management/${p.id}`)}
                                    className="font-bold text-gray-800 text-lg hover:text-red-600 text-left"
                                >
                                    {p.productOrService}
                                </button>
                                <span className={`px-2 py-1 rounded text-xs font-medium ${getStatusColor(p.status)}`}>
                                    {p.status}
                                </span>
                            </div>
                            <p className="text-gray-600 text-sm mb-2 line-clamp-2">{p.description}</p>
                            <div className="flex flex-wrap gap-2 text-xs text-gray-500 mb-4">
                                <span>Solicitante: {p.requesterUsername}</span>
                                <span>• Cantidad: {p.quantity}</span>
                                <span>• {formatDate(p.createdAt)}</span>
                            </div>
                            <div>
                                <label className="block text-xs font-medium text-gray-600 mb-1">Cambiar estado:</label>
                                <select
                                    value={p.status}
                                    onChange={(e) => handleStatusChange(p.id, e.target.value)}
                                    disabled={statusLoading === p.id}
                                    className="w-full px-3 py-2 border border-gray-300 rounded-md text-sm focus:ring-red-500 focus:border-red-500 disabled:opacity-50"
                                >
                                    {PURCHASING_STATUSES.map((s) => (
                                        <option key={s} value={s}>{s}</option>
                                    ))}
                                </select>
                            </div>
                            <div className="mt-3 flex gap-2">
                                <button
                                    onClick={() => navigate(`/purchases/management/${p.id}`)}
                                    className="text-sm text-red-600 hover:underline font-medium"
                                >
                                    Ver detalle y cotizaciones
                                </button>
                                {p.referenceLink && (
                                    <a
                                        href={p.referenceLink}
                                        target="_blank"
                                        rel="noopener noreferrer"
                                        className="text-sm text-red-600 hover:underline"
                                    >
                                        Ver referencia →
                                    </a>
                                )}
                            </div>
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
};

export default PurchasingAgentDashboard;
